            forkyBlck, Opt.none(seq[BlobSidecar]),
            Opt.some(data_columns),
            checkValidator = true)
        else:
          await node.router.routeSignedBeaconBlock(
            forkyBlck, Opt.none(seq[BlobSidecar]),
            Opt.none(seq[fulu.DataColumnSidecar]),
            checkValidator = true)

